package dz.mawashi.app
import org.junit.Assert.assertEquals
import org.junit.Test
class FeedAccountingTest {
 @Test fun weightsPurchasesAvailableBeforeConsumptionOnSameDate(){val r=calculateFeedConsumptionAccounting(listOf(FeedConsumptionEntry("شعير",10.0,"2026-05-10")),listOf(FeedPurchaseCost("شعير",20.0,1000.0,"2026-05-01"),FeedPurchaseCost("شعير",30.0,1800.0,"2026-05-10")));assertEquals(560.0,r.totalCost,0.001);assertEquals(0.0,r.uncostedQuantityKg,0.001)}
 @Test fun ignoresPurchasesMadeAfterConsumption(){val r=calculateFeedConsumptionAccounting(listOf(FeedConsumptionEntry("شعير",5.0,"2026-05-10")),listOf(FeedPurchaseCost("شعير",10.0,500.0,"2026-05-11")));assertEquals(0.0,r.totalCost,0.001);assertEquals(5.0,r.uncostedQuantityKg,0.001)}
 @Test fun recalculatesMovingAverageAfterConsumptionAndLaterPurchase(){val r=calculateFeedConsumptionAccounting(listOf(FeedConsumptionEntry("شعير",2.0,"2026-05-05"),FeedConsumptionEntry("شعير",3.0,"2026-05-15")),listOf(FeedPurchaseCost("شعير",10.0,500.0,"2026-05-01"),FeedPurchaseCost("شعير",10.0,1500.0,"2026-05-10")));assertEquals(100.0+3.0*((8.0*50.0+10.0*150.0)/18.0),r.totalCost,0.001);assertEquals(0.0,r.uncostedQuantityKg,0.001)}
 @Test fun exposesUncostedQuantityWhenPurchaseOrDateIsMissing(){val r=calculateFeedConsumptionAccounting(listOf(FeedConsumptionEntry("نخالة",4.0,"2026-05-04"),FeedConsumptionEntry("شعير",2.0,"")),listOf(FeedPurchaseCost("شعير",10.0,500.0,"2026-05-01")));assertEquals(0.0,r.totalCost,0.001);assertEquals(6.0,r.uncostedQuantityKg,0.001)}
 @Test fun reportsOnlyQuantityExceedingPurchasedStockAsUncosted(){val r=calculateFeedConsumptionAccounting(listOf(FeedConsumptionEntry("شعير",12.0,"2026-05-10")),listOf(FeedPurchaseCost("شعير",10.0,500.0,"2026-05-01")));assertEquals(500.0,r.totalCost,0.001);assertEquals(2.0,r.uncostedQuantityKg,0.001)}
 @Test fun ignoresInvalidPurchaseAndConsumptionQuantities(){val r=calculateFeedConsumptionAccounting(listOf(FeedConsumptionEntry("شعير",-5.0,"2026-05-10"),FeedConsumptionEntry("شعير",Double.NaN,"2026-05-10")),listOf(FeedPurchaseCost("شعير",0.0,100.0,"2026-05-01"),FeedPurchaseCost("شعير",10.0,-20.0,"2026-05-01")));assertEquals(0.0,r.totalCost,0.001);assertEquals(0.0,r.uncostedQuantityKg,0.001)}
 @Test fun feedSalesReduceInventoryBeforeLaterConsumptionAndUseMovingAverage(){val r=calculateFeedConsumptionAccounting(listOf(FeedConsumptionEntry("شعير",2.0,"2026-05-15")),listOf(FeedPurchaseCost("شعير",10.0,500.0,"2026-05-01"),FeedPurchaseCost("شعير",10.0,1500.0,"2026-05-10")),listOf(FeedSaleEntry("S1","شعير",4.0,"2026-05-12")));assertEquals(4.0*100.0,r.totalSaleCost,0.001);assertEquals(2.0*100.0,r.totalCost,0.001);assertEquals(0.0,r.uncostedSaleQuantityKg,0.001)}
 @Test fun saleCostIsSeparatedFromOperatingConsumptionCost(){val r=calculateFeedConsumptionAccounting(listOf(FeedConsumptionEntry("شعير",3.0,"2026-05-02")),listOf(FeedPurchaseCost("شعير",10.0,500.0,"2026-05-01")),listOf(FeedSaleEntry("S1","شعير",2.0,"2026-05-03")));assertEquals(150.0,r.totalCost,0.001);assertEquals(100.0,r.totalSaleCost,0.001)}
 @Test fun reportsFeedSalesWithoutDocumentedCost(){val r=calculateFeedConsumptionAccounting(emptyList(),emptyList(),listOf(FeedSaleEntry("S1","شعير",5.0,"2026-05-03")));assertEquals(0.0,r.totalSaleCost,0.001);assertEquals(5.0,r.uncostedSaleQuantityKg,0.001)}
 @Test fun reportsOnlySaleQuantityExceedingCostedInventory(){val r=calculateFeedConsumptionAccounting(emptyList(),listOf(FeedPurchaseCost("شعير",3.0,300.0,"2026-05-01")),listOf(FeedSaleEntry("S1","شعير",5.0,"2026-05-03")));assertEquals(300.0,r.totalSaleCost,0.001);assertEquals(2.0,r.uncostedSaleQuantityKg,0.001)}
}
